    ('ovn-nog-197', '5d3819711cd679e23167e6b8e22930c1', '18a27165b21cb3d7f23dbcd71a26177c', '81df0bc0cbe60bf10e3db032e8625f32', 4, '5530dfa28b8ba661afda26204f5dea28'),
    ('ovn-nog-198', '5d3819711cd679e23167e6b8e22930c1', '9d85f704c246aaba34355a810ff05874', '81df0bc0cbe60bf10e3db032e8625f32', 2, '564e4f95232dbf43bb978f910e83a51d'),
    ('ovn-nog-199', '5d3819711cd679e23167e6b8e22930c1', 'b22fccbba96d2f2e615ada892ebbf3cc', '81df0bc0cbe60bf10e3db032e8625f32', 0, '930c38299713236f647f31cd61048040'),
    ('ovn-nog-200', '5d3819711cd679e23167e6b8e22930c1', 'a261a4a3eec03ea92249f98046807abb', '81df0bc0cbe60bf10e3db032e8625f32', 3, '9c27be3c5def550f77bac6d205dec059')
    ) as v(id, prompt_md5, passage_md5, options_md5, correct_index, explain_md5)
  loop
    if exists (select 1 from public.questions q where q.id = fix.id) then
      present := present + 1;
    end if;
    if exists (
      select 1 from public.questions q
       where q.id = fix.id
         and q.status = 'draft'
         and q.verification = 'agreed'
         and md5(q.prompt) = fix.prompt_md5
         and md5(q.passage) is not distinct from fix.passage_md5
         and md5(q.options::text) = fix.options_md5
         and q.correct_index = fix.correct_index
         and md5(q.explain) = fix.explain_md5
    ) then
      ok := ok || fix.id;
    elsif exists (select 1 from public.questions q where q.id = fix.id and q.status <> 'published') then
      skipped := skipped || fix.id;
    end if;
  end loop;

  if present = 0 then
    raise notice '0027: de nya frågorna finns inte i databasen; inget görs.';
    return;
  end if;

  update public.questions set status = 'published' where id = any(ok);

  raise notice '0027: % publicerade, % hoppades över: %', coalesce(array_length(ok, 1), 0),
    coalesce(array_length(skipped, 1), 0), array_to_string(skipped, ', ');
end
